-- ====================================================================
-- SKRIP PERBAIKAN NAVIGASI SIDEBAR & SISTEM KASIR/RESERVASI (PRODUCTION)
-- File         : 02_fix_navigation_production.sql
-- Compatibility: MySQL 8.0+ / MariaDB / Railway Production / DBeaver
-- Keterangan   : Menghapus menu lama 'Contoh & Template', memasang Unique Key,
--                meng-update menu PMS (Kasir, Front Office, Reservasi, Housekeeping)
--                untuk seluruh role, serta memastikan format sequence tersedia.
-- ====================================================================

SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

-- --------------------------------------------------------------------
-- [LANGKAH 1] BERSIHKAN DATA DUPLIKAT DI `mst_navigation`
-- --------------------------------------------------------------------
-- Menghapus entri menu duplikat terdahulu (seperti ID 7 lama) dan menjaga ID tertinggi
DELETE n1 FROM `mst_navigation` n1
JOIN `mst_navigation` n2 
  ON LOWER(TRIM(n1.`role`)) = LOWER(TRIM(n2.`role`)) AND n1.`id` < n2.`id`;

-- --------------------------------------------------------------------
-- [LANGKAH 2] PASANG UNIQUE KEY PADA KOLOM `role` DI `mst_navigation`
-- --------------------------------------------------------------------
SET @idx_exists := (
  SELECT COUNT(*) 
  FROM INFORMATION_SCHEMA.STATISTICS 
  WHERE TABLE_SCHEMA = DATABASE() 
    AND TABLE_NAME = 'mst_navigation' 
    AND INDEX_NAME = 'uq_navigation_role'
);
SET @stmt_sql := IF(
  @idx_exists = 0, 
  'ALTER TABLE `mst_navigation` ADD UNIQUE KEY `uq_navigation_role` (`role`)', 
  'SELECT 1'
);
PREPARE exec_stmt FROM @stmt_sql;
EXECUTE exec_stmt;
DEALLOCATE PREPARE exec_stmt;

-- --------------------------------------------------------------------
-- [LANGKAH 3] UPDATE / INSERT MENU PMS LENGKAP KE `mst_navigation`
-- --------------------------------------------------------------------

