-- --------------------------------------------------------------------
-- [LANGKAH 4] SINKRONISASI TABEL `user_navigation` (OVERRIDE PER USER)
-- --------------------------------------------------------------------
-- Pastikan user_navigation untuk akun superadmin/admin juga diperbarui
UPDATE `user_navigation`
SET `menu` = (SELECT `menu` FROM `mst_navigation` WHERE `role` = 'superadmin' LIMIT 1),
    `updated_at` = NOW()
WHERE `user_code` = 'USR000000' OR `user_code` IN (SELECT `user_code` FROM `mst_user` WHERE `role` IN ('superadmin', 'admin', 'master'));

-- --------------------------------------------------------------------
-- [LANGKAH 5] PASTIKAN FORMAT PENOMORAN TRANSAKSI TERSEDIA
-- --------------------------------------------------------------------
INSERT INTO `sys_format_penomoran` (`kode_format`, `nama_tabel`, `prefix`, `panjang_digit`, `nomor_terakhir`, `is_active`, `created_at`, `updated_at`)
VALUES 
  ('FMT-MSTSHIFT', 'mst_shift', 'SFT', 4, 6, 1, NOW(), NOW()),
  ('FMT-RESERVASI', 'trx_reservasi', 'RES', 6, 10, 1, NOW(), NOW()),
  ('FMT-CHECKIN', 'trx_checkin', 'CHK', 6, 8, 1, NOW(), NOW()),
  ('FMT-FOLIO', 'trx_folio', 'FOL', 6, 10, 1, NOW(), NOW()),
  ('FMT-TRANSAKSI', 'trx_transaksi', 'TRX', 6, 25, 1, NOW(), NOW()),
  ('FMT-INVOICE', 'trx_invoice', 'INV', 6, 5, 1, NOW(), NOW()),
  ('FMT-NA', 'trx_night_audit', 'NA', 6, 3, 1, NOW(), NOW()),
  ('FMT-REFUND', 'trx_refund', 'REF', 6, 0, 1, NOW(), NOW())
ON DUPLICATE KEY UPDATE 
  `prefix` = VALUES(`prefix`),
  `panjang_digit` = VALUES(`panjang_digit`),
  `is_active` = 1,
  `updated_at` = NOW();

SET FOREIGN_KEY_CHECKS = 1;

-- --------------------------------------------------------------------
-- [LANGKAH 6] VERIFIKASI HASIL UPDATE NAVIGASI
-- --------------------------------------------------------------------
SELECT 
  `id`,
  `role`,
  CHAR_LENGTH(`menu`) AS `menu_char_length`,
  IF(LOCATE('Contoh', `menu`) > 0, '⚠️ MASIH ADA CONTOH', '✅ BERSIH') AS `status_contoh`,
  IF(LOCATE('Reservasi', `menu`) > 0, '✅ ADA RESERVASI', '❌ TIDAK ADA') AS `status_reservasi`,
  IF(LOCATE('Kasir', `menu`) > 0, '✅ ADA KASIR', '❌ TIDAK ADA') AS `status_kasir`,
  IF(LOCATE('Housekeeping', `menu`) > 0, '✅ ADA HOUSEKEEPING', '❌ TIDAK ADA') AS `status_housekeeping`,
  `updated_at`
FROM `mst_navigation`
ORDER BY `id` ASC;
